document.querySelectorAll('.warehouse-status').forEach(function(sel){var form=sel.closest('form'),row=sel.closest('tr'),ordered=row.querySelector('.ordered-date'),handoff=row.querySelector('.handoff-btn');function syncStock(){var v=sel.value;ordered.hidden=v!=='Поръчана';handoff.disabled=v!=='Налична';}sel.addEventListener('change',syncStock);syncStock();});
document.querySelectorAll('.datetime24').forEach(function(box){var d=box.querySelector('.date24'),t=box.querySelector('.time24'),h=box.querySelector('.datetime24-hidden'),today=box.querySelector('.today-datetime');function sync(){var m=d.value.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/),tm=t.value.trim().match(/^([01]\d|2[0-3]):([0-5]\d)$/);h.value=m&&tm?m[3]+'-'+m[2]+'-'+m[1]+'T'+tm[0]:'';}d.addEventListener('input',sync);t.addEventListener('input',sync);today.addEventListener('click',function(){var n=new Date(),pad=x=>String(x).padStart(2,'0');d.value=pad(n.getDate())+'-'+pad(n.getMonth()+1)+'-'+n.getFullYear();if(!t.value)t.value=pad(n.getHours())+':'+pad(n.getMinutes());sync();});});
document.querySelectorAll('.today-field').forEach(function(btn){btn.addEventListener('click',function(){var input=btn.parentElement.querySelector('input[type=date]'),d=new Date(),pad=n=>String(n).padStart(2,'0');input.value=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());input.dispatchEvent(new Event('change',{bubbles:true}));});});
document.querySelectorAll('[name=client_kind]').forEach(function(select){function sync(){var fieldset=select.closest('form').querySelector('.company-data');if(fieldset)fieldset.hidden=select.value!=='company';}select.addEventListener('change',sync);sync();});
async function registryLoad(input){var form=input.closest('form'),msg=form.querySelector('.registry-message'),value=(input.value||'').replace(/\D/g,'');if(!/^(\d{9}|\d{13})$/.test(value))return;if(input.dataset.loading==='1'||input.dataset.loaded===value)return;input.dataset.loading='1';msg.textContent='Зареждане…';try{var res=await fetch('/company-registry.php?uic='+encodeURIComponent(value),{credentials:'same-origin',headers:{Accept:'application/json'}}),data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error||'Неуспешна справка.');input.value=data.uic||value;input.dataset.loaded=value;form.querySelector('[name=company_legal_name]').value=data.companyName||'';form.querySelector('[name=representative]').value=data.representative||'';msg.textContent='Заредено: '+(data.companyName||data.uic);}catch(e){msg.textContent=e.message||'Неуспешно зареждане.';}finally{input.dataset.loading='0';}}
document.querySelectorAll('.registry-uic').forEach(function(input){var timer;input.addEventListener('input',function(){clearTimeout(timer);input.dataset.loaded='';var v=(input.value||'').replace(/\D/g,'');if(v.length===9||v.length===13)timer=setTimeout(function(){registryLoad(input);},300);});input.addEventListener('change',function(){registryLoad(input);});input.addEventListener('blur',function(){registryLoad(input);});});
</script>

